package com.hmdp.ai.application.artifact;import com.hmdp.ai.application.security.AiAccessGuard;import com.hmdp.ai.domain.artifact.*;import com.hmdp.ai.domain.knowledge.ObjectStoragePort;import com.hmdp.ai.domain.security.*;import com.hmdp.exception.BusinessException;import org.junit.jupiter.api.Test;import java.util.*;import static org.assertj.core.api.Assertions.assertThatThrownBy;import static org.mockito.Mockito.*;
class ArtifactApplicationServiceTest {@Test void rejectsArtifactOwnedByAnotherUser(){ArtifactRepository repository=mock(ArtifactRepository.class);ObjectStoragePort storage=mock(ObjectStoragePort.class);AiAccessGuard access=mock(AiAccessGuard.class);AiSecurityContext context=new AiSecurityContext("user-a",new TenantContext("t"),new WorkspaceContext("w"),new AuthorizationContext(EnumSet.of(AiPermission.AGENT_RUN)),false);when(access.require(AiPermission.AGENT_RUN)).thenReturn(context);when(repository.find("t","w","artifact")).thenReturn(Optional.of(new ArtifactRecord("artifact","t","w","run","file.txt","text/plain","key",4,"user-b","ACTIVE")));ArtifactApplicationService service=new ArtifactApplicationService(repository,storage,access,"bucket");assertThatThrownBy(()->service.download("artifact")).isInstanceOf(BusinessException.class);verifyNoInteractions(storage);}@Test void scopesLookupToCurrentTenantAndWorkspace(){ArtifactRepository repository=mock(ArtifactRepository.class);AiAccessGuard access=mock(AiAccessGuard.class);AiSecurityContext context=new AiSecurityContext("user",new TenantContext("tenant-a"),new WorkspaceContext("workspace-a"),new AuthorizationContext(EnumSet.of(AiPermission.AGENT_RUN)),false);when(access.require(AiPermission.AGENT_RUN)).thenReturn(context);when(repository.find("tenant-a","workspace-a","artifact")).thenReturn(Optional.empty());ArtifactApplicationService service=new ArtifactApplicationService(repository,mock(ObjectStoragePort.class),access,"bucket");assertThatThrownBy(()->service.download("artifact")).hasMessage("ARTIFACT_NOT_FOUND");verify(repository).find("tenant-a","workspace-a","artifact");}}
